\u043d\u0456\u0449\u043e \u043c\u0430\u0432\u043a\u0430___\u0437\u043c\u0456\u043d\u0438\u0442\u0438_\u0435\u043b\u0435\u043c\u0435\u043d\u0442(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_862, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_863, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_864, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_865, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_866);
\u043d\u0456\u0449\u043e \u043c\u0430\u0432\u043a\u0430___\u043f\u0440\u0435\u0434\u043c\u0435\u0442_\u0434\u0430\u043d\u0438\u0445_\u0437\u043c\u0456\u043d\u0438\u0442\u0438_\u0435\u043b\u0435\u043c\u0435\u043d\u0442(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_894, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_895, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_896, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_897, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_898);
\u043d\u0456\u0449\u043e \u043c\u0430\u0432\u043a\u0430___\u043f\u0440\u0435\u0434\u043c\u0435\u0442_\u0441\u043b\u043e\u0432\u043d\u0438\u043a\u0430_\u0437\u043c\u0456\u043d\u0438\u0442\u0438_\u0435\u043b\u0435\u043c\u0435\u043d\u0442(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_908, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_909, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_910, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_911, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_912);
\u043d\u0456\u0449\u043e \u043c\u0430\u0432\u043a\u0430___\u043f\u0440\u0435\u0434\u043c\u0435\u0442_\u0441\u043f\u0438\u0441\u043a\u0443_\u0437\u043c\u0456\u043d\u0438\u0442\u0438_\u0435\u043b\u0435\u043c\u0435\u043d\u0442(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_922, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_923, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_924, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_925, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_926);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u043f\u043e\u043a\u043b\u0430\u0441\u0442\u0438_\u0441\u043f\u0440\u043e\u0431\u0443(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_941, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_942, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_943, \u043f32 \u043d\u0430\u0437\u0432\u0430_944);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438_\u043c\u043e\u0434\u0443\u043b\u044c(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_950, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_951);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438_\u043e\u0437\u043d\u0430\u043a\u0443(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_955, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_956, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_957, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_958);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438_\u0441\u043f\u0438\u0441\u043e\u043a(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_964, \u043f32 \u043d\u0430\u0437\u0432\u0430_965);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438_\u043f\u043e\u043c\u0438\u043b\u043a\u0443(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_969, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_970);
\u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043c\u0430\u0432\u043a\u0430___\u043e\u0442\u0440\u0438\u043c\u0430\u0442\u0438_\u043f\u0435\u0440\u0435\u0431\u0456\u0440(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_974, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_975, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_976);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438_\u043f\u0435\u0440\u0435\u0431\u0456\u0440_\u0434\u0430\u043d\u0438\u0445(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_991, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_992);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438_\u043f\u0435\u0440\u0435\u0431\u0456\u0440_\u043f\u0440\u043e\u043c\u0456\u0436\u043a\u0430_\u0447\u0438\u0441\u0435\u043b(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_999, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1000);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438_\u043f\u0435\u0440\u0435\u0431\u0456\u0440_\u043f\u043e\u0441\u043b\u0456\u0434\u043e\u0432\u043d\u043e\u0441\u0442\u0456(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1006, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1007);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438_\u043f\u0435\u0440\u0435\u0431\u0456\u0440_\u0441\u043b\u043e\u0432\u043d\u0438\u043a\u0430(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1013, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1014);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438_\u043f\u0435\u0440\u0435\u0431\u0456\u0440_\u0441\u043f\u0438\u0441\u043a\u0443(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1020, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1021);
\u0430\u0434\u0440\u0435\u0441\u0430 \u043c\u0430\u0432\u043a\u0430___\u0441\u0442\u0432\u043e\u0440\u0438\u0442\u0438_\u043f\u0435\u0440\u0435\u0431\u0456\u0440_\u0442\u0435\u043a\u0441\u0442\u0443(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1027, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1028);
\u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043c\u0430\u0432\u043a\u0430___\u043e\u0442\u0440\u0438\u043c\u0430\u0442\u0438_\u0435\u043b\u0435\u043c\u0435\u043d\u0442(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1041, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_1042, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_1043, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_1044);
\u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043c\u0430\u0432\u043a\u0430___\u043f\u0440\u0435\u0434\u043c\u0435\u0442_\u0434\u0430\u043d\u0438\u0445_\u043e\u0442\u0440\u0438\u043c\u0430\u0442\u0438_\u0435\u043b\u0435\u043c\u0435\u043d\u0442(\u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1058, \u0430\u0434\u0440\u0435\u0441\u0430 \u043d\u0430\u0437\u0432\u0430_1059, \u0443\u043d\u0456\u043a___37___\u043c\u0430\u0432\u043a\u0430___\u0417\u043d\u0430\u0447\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_1060, \u0443\u043d\u0456\u043a___15___\u043c\u0430\u0432\u043a\u0430___\u041c\u0456\u0441\u0446\u0435\u0437\u043d\u0430\u0445\u043e\u0434\u0436\u0435\u043d\u043d\u044f \u043d\u0430\u0437\u0432\u0430_1061);
